// MARK: - Boxes

/// A value one thread fills in and another reads. Used where a completion
/// handler outlives the call that started it.
private final class Box<T> {
    private var value: T
    private let lock = NSLock()

    init(_ initial: T) { value = initial }

    func mutate(_ body: (inout T) -> Void) {
        lock.lock()
        defer { lock.unlock() }
        body(&value)
    }

    var current: T {
        lock.lock()
        defer { lock.unlock() }
        return value
    }
}

// MARK: - Watches

struct RunOutcome {
    var ok = false
    var code = -1
    var out = ""
    var err = ""
}

struct HTTPOutcome {
    var ok = false
    var status = 0
    var out = ""
}

struct LaunchAgentOutcome {
    var installed = false
    var loaded = false
    var running = false
    var enabled = true
    var pid = 0
    var label = ""
    var plist = "" // expanded
}

/// Where a user's own LaunchAgents live, and how launchctl is told about them.
enum Launchd {
    /// Read at runtime because it is the one part of addressing an agent that
    /// differs between Macs: 501 is only the first account a Mac creates.
    static var domain: String { "gui/\(getuid())" }

    static func target(_ label: String) -> String { domain + "/" + label }

    /// launchctl is handed argv directly, with no shell to expand a tilde.
    static func expand(_ path: String) -> String { (path as NSString).expandingTildeInPath }

    /// Whether launchd's disabled database holds the label off, which is what
    /// keeps it from loading at login. A label it has no entry for is enabled.
    /// Older macOS writes `=> true` where 27 writes `=> disabled`.
    static func disabled(_ label: String) -> Bool {
        let printed = Watcher.run(["launchctl", "print-disabled", domain], timeout: 10)
        let key = "\"" + label + "\" => "
        for line in printed.out.split(separator: "\n") {
            let field = line.trimmingCharacters(in: .whitespaces)
            guard field.hasPrefix(key) else { continue }
            let value = field.dropFirst(key.count)
            return value == "disabled" || value == "true"
        }
        return false
    }
}

enum Watcher {
    /// Output past this is read and dropped, so a child that never stops
    /// printing neither stalls on a full pipe nor grows the app without bound.
    static let outputCap = 4 << 20

    /// Runs argv directly — never a shell. /usr/bin/env performs the PATH
    /// lookup, which a LaunchAgent's minimal environment would otherwise miss.
    ///
    /// The child leads its own process group, so a timeout stops everything it
    /// started, even what outlives the child. A child that exits on its own
    /// leaves its descendants a second to let go of its pipes, and then alone:
    /// a poll does not wait on a daemon.
    static func run(_ argv: [String], timeout: TimeInterval? = nil) -> RunOutcome {
        guard !argv.isEmpty else { return RunOutcome() }
        var outFDs: [Int32] = [-1, -1]
        var errFDs: [Int32] = [-1, -1]
        guard pipe(&outFDs) == 0 else { return failed("pipe: " + String(cString: strerror(errno))) }
        guard pipe(&errFDs) == 0 else {
            outFDs.forEach { close($0) }
            return failed("pipe: " + String(cString: strerror(errno)))
        }

        var actions: posix_spawn_file_actions_t?
        posix_spawn_file_actions_init(&actions)
        defer { posix_spawn_file_actions_destroy(&actions) }
        posix_spawn_file_actions_addopen(&actions, 0, "/dev/null", O_RDONLY, 0)
        posix_spawn_file_actions_adddup2(&actions, outFDs[1], 1)
        posix_spawn_file_actions_adddup2(&actions, errFDs[1], 2)

        var attr: posix_spawnattr_t?
        posix_spawnattr_init(&attr)
        defer { posix_spawnattr_destroy(&attr) }
        // CLOEXEC_DEFAULT keeps the app's own descriptors out of the child.
        posix_spawnattr_setflags(&attr, Int16(POSIX_SPAWN_SETPGROUP | POSIX_SPAWN_CLOEXEC_DEFAULT
            | POSIX_SPAWN_SETSIGDEF | POSIX_SPAWN_SETSIGMASK))
        posix_spawnattr_setpgroup(&attr, 0)
        var all = sigset_t()
        sigfillset(&all)
        posix_spawnattr_setsigdefault(&attr, &all)
        var none = sigset_t()
        sigemptyset(&none)
        posix_spawnattr_setsigmask(&attr, &none)

        var cargs: [UnsafeMutablePointer<CChar>?] = (["/usr/bin/env"] + argv).map { strdup($0) } + [nil]
        defer { cargs.forEach { free($0) } }
        var pid: pid_t = 0
        let spawned = posix_spawn(&pid, "/usr/bin/env", &actions, &attr, &cargs, environ)
        close(outFDs[1])
        close(errFDs[1])
        guard spawned == 0 else {
            close(outFDs[0])
            close(errFDs[0])
            return failed(String(cString: strerror(spawned)))
        }

        // Both pipes drain at once. Reading one to EOF and then the other
        // deadlocks a child that fills the second pipe's buffer meanwhile.
        var fds = [outFDs[0], errFDs[0]].map { fd -> pollfd in
            _ = fcntl(fd, F_SETFL, fcntl(fd, F_GETFL) | O_NONBLOCK)
            return pollfd(fd: fd, events: Int16(POLLIN), revents: 0)
        }
        var captured = [Capture(), Capture()]
        let started = Date()
        var status: Int32 = 0
        var exitedAt: Date?
        var termAt: Date?
        var killed = false
        while true {
            let open = fds.contains { $0.fd >= 0 }
            // Once a timeout has begun, the group is stopped whether or not the
            // child itself is still there to reap.
            let stopping = termAt != nil && !killed && killpg(pid, 0) == 0
            if let exitedAt, !stopping, !open || Date().timeIntervalSince(exitedAt) > 1 { break }
            if open {
                _ = poll(&fds, nfds_t(fds.count), 50)
            } else {
                usleep(20_000)
            }
            for i in fds.indices where fds[i].fd >= 0 && fds[i].revents != 0 {
                if !captured[i].drain(fds[i].fd) {
                    close(fds[i].fd)
                    fds[i].fd = -1
                }
            }
            if exitedAt == nil, waitpid(pid, &status, WNOHANG) == pid { exitedAt = Date() }
            guard let timeout else { continue }
            if termAt == nil, exitedAt == nil, Date().timeIntervalSince(started) >= timeout {
                killpg(pid, SIGTERM)
                termAt = Date()
            } else if let termAt, !killed, Date().timeIntervalSince(termAt) >= 2 {
                killpg(pid, SIGKILL)
                killed = true
            }
        }
        fds.filter { $0.fd >= 0 }.forEach { close($0.fd) }

        var notes: [String] = []
        if let timeout, termAt != nil { notes.append("perch: stopped after \(seconds(timeout)), its timeout") }
        for (i, name) in ["stdout", "stderr"].enumerated() where captured[i].dropped > 0 {
            notes.append("perch: \(name) cut at \(outputCap) bytes; \(captured[i].dropped) more dropped")
        }
        // A wait status: the low seven bits are the signal, zero for an exit.
        let signal = status & 0x7f
        let code = termAt != nil ? -1 : Int(signal == 0 ? (status >> 8) & 0xff : signal)
        var err = String(decoding: captured[1].data, as: UTF8.self)
        for note in notes {
            if !err.isEmpty, !err.hasSuffix("\n") { err += "\n" }
            err += note + "\n"
        }
        return RunOutcome(
            ok: code == 0,
            code: code,
            out: String(decoding: captured[0].data, as: UTF8.self),
            err: err
        )
    }

    private static func failed(_ why: String) -> RunOutcome {
        RunOutcome(ok: false, code: -1, out: "", err: why)
    }

    private static func seconds(_ t: TimeInterval) -> String {
        t == t.rounded() ? "\(Int(t))s" : "\(t)s"
    }

    private struct Capture {
        var data = Data()
        var dropped = 0

        /// Reads what the pipe holds now. False once it reaches EOF.
        mutating func drain(_ fd: Int32) -> Bool {
            var chunk = [UInt8](repeating: 0, count: 1 << 16)
            while true {
                let n = read(fd, &chunk, chunk.count)
                if n > 0 {
                    let room = max(0, Watcher.outputCap - data.count)
                    data.append(contentsOf: chunk[0..<min(n, room)])
                    dropped += max(0, n - room)
                } else if n < 0, errno == EINTR {
                    continue
                } else {
                    return n < 0 && errno == EAGAIN
                }
            }
        }
    }

    static func http(_ urlString: String) -> HTTPOutcome {
        guard let url = URL(string: urlString) else { return HTTPOutcome() }
        // Boxed because the wait below can time out while the request is still
        // in flight, leaving the handler to write after this call has returned.
        let box = Box(HTTPOutcome())
        let done = DispatchSemaphore(value: 0)
        var request = URLRequest(url: url)
        request.timeoutInterval = 5
        URLSession.shared.dataTask(with: request) { data, response, _ in
            box.mutate { outcome in
                if let http = response as? HTTPURLResponse {
                    outcome.status = http.statusCode
                    outcome.ok = (200..<300).contains(http.statusCode)
                }
                if let data { outcome.out = String(data: data, encoding: .utf8) ?? "" }
            }
            done.signal()
        }.resume()
        _ = done.wait(timeout: .now() + 10)
        return box.current
    }

    static func exists(_ path: String) -> Bool {
        FileManager.default.fileExists(atPath: (path as NSString).expandingTildeInPath)
    }

    /// `launchctl print` exiting 0 says launchd knows the label, which is not
    /// the same as the job having a process: one that has run and exited is
    /// still loaded. The top-level `state =` line is what separates the two,
    /// and it is exactly one tab in — deeper ones describe the job's endpoints
    /// and are active whether or not the job itself is.
    static func launchAgent(label: String, plist: String) -> LaunchAgentOutcome {
        var o = LaunchAgentOutcome(label: label, plist: Launchd.expand(plist))
        o.installed = FileManager.default.fileExists(atPath: o.plist)
        o.enabled = !Launchd.disabled(label)
        let printed = run(["launchctl", "print", Launchd.target(label)], timeout: 10)
        o.loaded = printed.ok
        guard printed.ok else { return o }
        for line in printed.out.split(separator: "\n", omittingEmptySubsequences: false) {
            guard line.hasPrefix("\t"), !line.hasPrefix("\t\t") else { continue }
            let field = line.dropFirst()
            if field.hasPrefix("state = ") { o.running = field.dropFirst(8) == "running" }
            if field.hasPrefix("pid = ") { o.pid = Int(field.dropFirst(6)) ?? 0 }
        }
        return o
    }
}

// MARK: - Menu

/// An NSMenuItem that carries its own closure, so the generated menu builder
/// does not need a selector per action.
final class ActionItem: NSMenuItem {
    private let handler: () -> Void

    init(title: String, handler: @escaping () -> Void) {
        self.handler = handler
        super.init(title: title, action: nil, keyEquivalent: "")
        self.target = self
        self.action = #selector(fire)
    }

    @available(*, unavailable)
    required init(coder: NSCoder) { fatalError("not supported") }

    @objc private func fire() { handler() }
}

// MARK: - Face and menu

/// What the status item shows, decided from one poll's results.
struct Face {
    var icon: MenuIcon
    var tint: Tint? = nil
    var dim = false
    var badge = ""
}

/// What agent: does to a LaunchAgent. Closed, because each one is a launchctl
/// invocation perch writes rather than the author.
enum LaunchAgentVerb: String {
    case start, stop, restart, enable, disable

    var gerund: String {
        switch self {
        case .start: return "Starting"
        case .stop: return "Stopping"
        case .restart: return "Restarting"
        case .enable: return "Enabling"
        case .disable: return "Disabling"
        }
    }
}

/// What activating a menu item does. It is lowered when the menu is built, so
/// an item runs what it showed.
enum WindowVerb {
    case open
    case close
    case reload
}

enum MenuAction {
    case run([String])
    case open(String)
    case post(url: String, body: String)
    case agent(label: String, plist: String, verb: LaunchAgentVerb)
    case swift(() -> Void)
    case window(WindowVerb)
    case quit
}
